window.APP_ESSAY_PAPERS["pol2-交通警察學"] = [{"roc":115,"mins":120,"src":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=115060&c=207&s=0913&q=1","qs":[{"n":1,"q":"為推動唾液毒品快篩試劑成為第一線員警執法檢測工具，並明確對車輛駕駛人實施唾液毒品快篩試劑測試檢定之相關檢測及拒絶配合實施測試檢定處置等程序，交通部增訂「違反道路交通管理事件統一裁罰標準及處理細則」第 19 條之 4，請說明該條文重點為何？（25 分）","pt":25},{"n":2,"q":"「道路交通管理處罰條例」第 21 條、第 21 條之 1，針對無照駕駛之處罰規定，114 年 11 月 19 日總統公布修正重點為何？（15 分）另第 35 條增訂酒駕強制抽血程序，其規定為何？（10 分）","pt":25},{"n":3,"q":"為保障用路人交通安全，內政部警政署業函頒「取締疑似施用毒品後駕車作業程序」，依該作業程序，請說明員警在攔停車輛後，執行觀察與研判時應有之作為與注意事項為何？（15 分）如駕駛人拒絕配合檢測時，又應如何作為？（10 分）","pt":25},{"n":4,"q":"近年來自駕車科技快速發展並逐漸普及，自動輔助駕駛系統（Advanced Driver Assistance Systems, ADAS）是利用感測器（如攝影機、雷達）偵測環境，協助駕駛操作的智慧系統，部分駕駛人認為自動輔助駕駛系統可取代人工駕駛，實際上，目前自動輔助駕駛系統發展尚未完全成熟，使用不當將危害安全。駕駛人使用自動輔助駕駛系統，遇有那些狀況或情境，將導致 ADAS 感測器無法辨識或誤判？（10 分）如不當使用，例如：行駛中將雙手放開未握在方向盤上，此種行為依「道路交通管理處罰條例」之處罰規定為何？（15 分）","pt":25}]},{"roc":114,"mins":120,"src":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=114060&c=507&s=1013&q=1","qs":[{"n":1,"q":"民國 113 年 1 月 1 日施行之道路交通安全基本法確立九大面向之基本政策，並規範道路交通安全計畫及道安推動組織，為讓道安工作有整體計畫遵循與落實：2 個與警察道安工作關係最密切面向之內涵。          （9 分）基本法對於各級政府道路交通安全計畫之架構關係與辦理年期為何？（6 分）113 至 116 年期國家道安計畫」中，警察機關推動計畫所針對之課題與對應採行策略提出看法。（10 分）","pt":25},{"n":2,"q":"自用小客車駕駛人於 10 年內第 2 次違反「酒精濃度超過規定標準」之規定，如肇事致人死亡者，從發生本起交通事故（設於 114 年 5 月）起一直到駕駛人再依規定考領駕駛執照時，請將前述期間自行區分階段，說明「道路交通管理處罰條例」對於該駕駛人、汽車所有人的相關處罰與規範有那些？（25 分）","pt":25},{"n":3,"q":"依據道路交通事故處理辦法之規定，警察機關應依交通事故案件當事人或利害關係人之申請，製作交通事故初步分析研判表：道路交通事故現場那些事項詳加勘察、蒐證與詢問關係人？（10 分）為是否即為肇事原因？請舉例並說明理由。（15 分）","pt":25},{"n":4,"q":"近日發生一起 78 歲長者駕車發生道路交通事故後涉嫌肇事逃逸，高速駛離時又釀成重大道路交通事故，該案讓高齡者換照等駕駛執照管理相關議題引發議論：75 歲以上高齡者定期換發駕照」制度之目的、制度實施日期後才屆滿 75 歲者之換照期限及駕照效期、不依規定辦理換照之處理機制。（15 分）以及制度實施對象與換照效期。  （10 分）","pt":25}]},{"roc":113,"mins":120,"src":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=113060&c=507&s=0915&q=1","qs":[{"n":1,"q":"依據法律，我國中央及地方政府「道路交通安全會報」之組織與任務為何？（25 分）","pt":25},{"n":2,"q":"近年新聞媒體常報導行人通行與安全問題，甚至稱臺灣是「行人地獄」，其產生原因為何？並就警察職權說明改善行人交通安全的執法策略及其法規依據。（25 分）","pt":25},{"n":3,"q":"警察依據「取締酒後駕車作業程序」計畫性勤務攔查各類車輛（汽機車、慢車等）駕駛人，檢測其酒精濃度後，各有不同酒精濃度的結果（未超過標準者、超過者等），各種結果該如何處置？（25 分）","pt":25},{"n":4,"q":"道路交通管理處罰條例規定「經以科學儀器取得證據資料證明其行為違規，得逕行舉發」，請問目前常使用的交通執法科學儀器有那些？以科學儀器取得證據資料得逕行舉發有那些限制條件或符合那些要件舉發才有法律效果？又如何精進科技執法？（25 分）","pt":25}]},{"roc":112,"mins":120,"src":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112070&c=507&s=1214&q=1","qs":[{"n":1,"q":"在取締酒後駕車作業程序與操作酒測器應注意那些事項？（25 分）","pt":25},{"n":2,"q":"警察人員執勤時，那些情形可以啟用警示燈或警鳴器依法行使交通優先權？（25 分）","pt":25},{"n":3,"q":"在「警力有限、民力無窮」概念下，各交通警察單位應受理民眾檢舉交通違規，試說明本項業務之法令依據、不予舉發之情形。（25 分）","pt":25},{"n":4,"q":"試列舉行人交通違規得以取締處罰的違規行為。（25 分）","pt":25}]},{"roc":111,"mins":120,"src":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=111070&c=507&s=1114&q=1","qs":[{"n":1,"q":"請以民國 111 年 5 月 4 日公布之道路交通管理處罰條例部分條文為依據：\n（一）說明「個人行動器具」     、「電動輔助自行車」  、「微型電動二輪車」之定義。（15 分）\n（二）除前述運具定義之內容以外，請以道路交通管理處罰條例之管理項目列表進行三種運具規範異同之比較。      （10 分）","pt":25},{"n":2,"q":"（一）請說明肇事致人受傷或死亡逃逸案件，在道路交通管理處罰條例第 62 條第 3 項與第 4 項，以及刑法第 185 條之 4 之規範內容。（10 分）\n（二）請以道路交通事故處理辦法為依據，說明處理肇事逃逸案件之要領。（15 分）","pt":25},{"n":3,"q":"（一）請圖示「A 車駕駛人於直行通過一無號誌路口前，一直到與橫向道路另一部 B 車輛發生碰撞時，現場所經歷的一系列事件（on-scene series」，並說明事件相關之意涵。of events）            （15 分）\n（二）請以 A 車駕駛人看到 B 車的感識反應距離與煞停距離，說明離路口多遠是 A 車駕駛人無法迴避事故的地點（point of no escape）（自行設定合理參數進行計算）。    （10 分）","pt":25},{"n":4,"q":"（一）請說明民國 110 年 12 月 22 日修正公布之道路交通管理處罰條例第 7條之 1 的重點。（15 分）\n（二）請以違反道路交通管理事件統一裁罰基準及處理細則為範圍，說明機關受理民眾檢舉違反道路交通管理事件之處理作法。       （10 分）","pt":25}]},{"roc":110,"mins":120,"src":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110070&c=507&s=1214&q=1","qs":[{"n":1,"q":"「區間測速」係國內近年來「科技執法」應用最廣泛的其中一項，試說明其運作原理以及遭遇的狀況。（25 分）","pt":25},{"n":2,"q":"道路交通事故案件當事人或利害關係人，依法得於特定期間內向警察機關申請閱覽或提供那些相關資料？（25 分）","pt":25},{"n":3,"q":"警察人員遇酒後駕車之汽車駕駛人拒絕出示身分證明文件或告知身分時，應如何實施強制作為？（25 分）","pt":25},{"n":4,"q":"違反道路交通管理事件，有那些情形應當場移置保管該汽車？有那些情形得逕行移置保管其車輛？（25 分）","pt":25}]},{"roc":109,"mins":120,"src":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109070&c=507&s=1016&q=1","qs":[{"n":1,"q":"交通部與內政部警政署正積極研用「科技執法」  ，以提高執法效率與節省警力，試舉例說明科技執法的應用。（25 分）","pt":25},{"n":2,"q":"交通事故肇事原因分析必須就當事人之「路權」加以研判，請說明汽車 行經交叉路口之路權優先次序如何規範？（25 分）","pt":25},{"n":3,"q":"請試述下列高快速公路名詞之意涵：（每小題 5 分，共 25 分）\n（一）減速車道\n（二）輔助車道\n（三）高乘載車道\n（四）交流道\n（五）匝道","pt":25},{"n":4,"q":"交通執法單位每年接受督考的績效指標，最常用的即是轄區內事故件數、事故死亡人數、事故受傷人數等，惟前述數字具有極高的隨機性，且因受督考單位轄區範圍大小（土地面積、人口數、車輛數等）而有特定影響。試說明如何規劃設計，可以比較公平有效地設定交通執法單位的績效指標，以達到促進交通安全的目標？（25 分）","pt":25}]},{"roc":108,"mins":120,"src":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=108070&c=507&s=1214&q=1","qs":[{"n":1,"q":"都會區交通壅塞，一直是世界各大都市所面臨棘手的問題，對每日通勤的上班族而言，無異是一場惡夢，也是身為交通警察每天必須疏導處理的工作。請問：\n（一）道路交通壅塞可概分為那幾類？（10 分）\n（二）你身為一位交通警察人員，請分析以上交通壅塞形成的原因各為何？（15 分）","pt":25},{"n":2,"q":"「酒後駕車，害人害己」已是社會大眾琅琅上口的一句話，但對於少數酒駕者而言，認為「只要未發生交通事故，拒絕警察酒測便可不受刑法制裁，罰錢了事而已」。請問：\n（一）依目前法規這種說法是否正確，理由為何？（10 分）\n（二）警察人員對於明顯酒後駕車之駕駛人，雖未肇事但拒絕接受酒精濃度測試檢定者，應踐行之執法程序（處置作為）為何？（15 分）","pt":25},{"n":3,"q":"交通事故發生時，很多人第一句話都會問「誰違規？」似乎違規的一方當事人便應負擔主要的肇事責任。請問：\n（一）這種說法你是否同意，理由為何？（10 分）\n（二）又很多交通事故發生的地點是位於無號誌化路（巷）口，請說明行車至無號誌化路（巷）口且無交通指揮人員指揮時，其行進、轉彎的路權規定為何？（15 分）","pt":25},{"n":4,"q":"警察單位經常會執行許多「交通專案」的重點性工作，在該專案期間，針對某項違規行為就是嚴格執法，對其他的違規行為可能就是另一套標準，造成民眾經常會有「為什麼昨天可以，今天就不行？」的昨是今非錯覺，也打擊了警察交通執法威信。請問：\n（一）如何利用科技智慧執法改善上述情形，達到「刑期於無刑」目標？（15 分）\n（二）而在運用科技執法之際，應有那些法律原則必須加以注意？（10 分）","pt":25}]},{"roc":107,"mins":120,"src":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107070&c=507&s=0914&q=1","qs":[{"n":1,"q":"教育、工程、執行為交通三 E 政策，目的在維護交通安全，而三者以交通執法、防制事故發生為基礎，請說明交通執法之意涵以及研訂交通執法策略之具體作法為何？（25 分）","pt":25},{"n":2,"q":"違反道路交通管理事件統一裁罰基準及處理細則第 6 條第 2 項規定：「公路主管及警察機關就其主管業務，查獲違反道路交通管理之行為者，應本於職權舉發或處理之。」請依道路交通管理處罰條例規定說明公路主管機關及警察機關之主管業務為何？（25 分）","pt":25},{"n":3,"q":"請依道路交通事故處理規範說明何謂「交通事故」？並說明交通事故初步處理後之分析研判要領為何？（25 分）","pt":25},{"n":4,"q":"國道車速快，常因瞬間疏忽釀成重大交通事故，國道警察執行勤務身處生死一線間，今年四月兩位國道警察盡忠職守，執行攔截製單舉發時，遭後車追撞因公殉職引起全國關注，學者專家提出應加強運用科技設備執法，您認為道路交通管理處罰條例之規定是否能維護國道執法人員之安全？請提出具體意見及加強運用科技設備執法之具體作為。（25 分）","pt":25}]},{"roc":106,"mins":120,"src":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106070&c=507&s=1113&q=1","qs":[{"n":1,"q":"機車為閃避前方突發險境而緊急煞車並傾倒滑行，機車並未碰觸任何外物，在滑行至靜止前於路面留下長度 15 公尺的刮地痕；當前廣泛採用的柏油路面機車刮地阻力係數（drag factor）為 0.53 至 0.65，試估算機車於刮地痕起點的速度。（25 分）","pt":25},{"n":2,"q":"除了肇事車輛的定位與照相外，請說明交通事故現場物證之蒐集主要還有那些項目？（25 分）","pt":25},{"n":3,"q":"道路交通事故現場測繪是一項極具技術性及技巧性的工作，所繪製之現場圖是研判肇事原因的主要依據之一。請具體說明現場測繪的對象與注意事項。（25 分）","pt":25},{"n":4,"q":"試比較雷達與雷射測速的原理及其差異。（25 分）","pt":25}]},{"roc":105,"mins":120,"src":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=105070&c=507&s=0914&q=1","qs":[{"n":1,"q":"請依據道路交通管理處罰條例之規定，分項說明交通警察之法定職權。（25 分）","pt":25},{"n":2,"q":"依據道路交通管理處罰條例相關規定，交通警察查獲違反道路交通管理事件之舉發方式及適用之法令規定為何？（25 分）","pt":25},{"n":3,"q":"依據道路交通管理處罰條例第 35 條第 4 項規定，汽車駕駛人行經警察機關設有告示執行測試檢定之處所，不依指示停車檢查，或拒絕測試檢定者，其罰則為何？又警察人員執行測試勤務時，應如何防範遭受危害？（25 分）","pt":25},{"n":4,"q":"國道於凌晨時段迭有車輛自撞護欄或追撞受傷事故。駕駛人依法規定需於現地標繪車輛位置，常遭後方來車追撞，造成更嚴重之死傷事故。為防制國道二次事故發生，你認為相關機關未來可以有那些策進作為（或創新作為）？（25 分）","pt":25}]},{"roc":104,"mins":120,"src":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=104070&c=507&s=0914&q=1","qs":[{"n":1,"q":"依據道路交通安全規則第 93 條第 2 項規定，消防車、救護車、警備車及工程救險車執行緊急任務時，得不受那些限制？另依道路交通管理處罰條例第 45 條規定，有那些妨害上述執行緊急任務之違規行為必須接受處罰？又依同條例第 7 條之 2 規定，如以逕行舉發時，應如何為之？（25 分）","pt":25},{"n":2,"q":"依道路交通管理處罰條例第 35 條規定，汽車駕駛人酒後駕駛汽車未肇事，拒絕接受酒精濃度測試檢定之罰則為何？以及警察人員必須踐行的執法程序為何？（25 分）","pt":25},{"n":3,"q":"依道路交通事故處理辦法規定，何謂重大交通事故？警察機關從獲知道路交通事故至到達現場，應視情況為那些處置？（25 分）","pt":25},{"n":4,"q":"根據統計，機車傷亡事故以 18 至 25 歲的年輕人及 65 歲以上的老年人偏高，請就交通安全管理及教育宣導的方向提出改善建議？（25 分）","pt":25}]},{"roc":103,"mins":120,"src":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=103070&c=507&s=1706&q=1","qs":[{"n":1,"q":"民國 103 年 1 月 8 日修正公布並於 3 月 31 日正式上路之新修「道路交通管理處罰條例」對慢車駕駛人罰鍰之新增規定為何？（25 分）","pt":25},{"n":2,"q":"道路交通事故現場所遺留之煞車痕(skid marks)與因轉彎過急所留下之側向滑痕(yaw marks)，都有助於事故處理人員藉以推估事故發生當時相關車輛之行車速率，請問此二者之成因為何？又根據二者之特徵所求得的車速在本質上有何不同？（25 分）","pt":25},{"n":3,"q":"請說明道路交通事故之定義，並論述「腳踏車在河濱公園的自行車道互撞，算不算道路交通事故」？（25 分）","pt":25},{"n":4,"q":"道路交通管理處罰條例與道路交通安全規則中有關「禁止其駕駛」與「不得駕車」之規定為何？對於禁駛應如何執行之？（25 分）","pt":25}]},{"roc":102,"mins":120,"src":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=102080&c=508&s=1611&q=1","qs":[{"n":1,"q":"逕行舉發交通違規行為須以固定式科學儀器取得證據資料，但那些汽車駕駛人違規行為不在此限？原因何在？（25 分）","pt":25},{"n":2,"q":"國道五號高速公路雪山隧道內，於 100 年 5 月發生通車 6 年來最嚴重的火燒車事故；請簡述個人對該事件的認識，並詳細敘述交通警察應有之作為。（25 分）","pt":25},{"n":3,"q":"自中華民國 102 年 1 月 1 日起，「道路交通安全規則」與「道路交通管理處罰條例」對取締酒後駕車的標準與罰則有何變革？請詳細說明之。（25 分）","pt":25},{"n":4,"q":"依據道路交通事故處理辦法，試回答構成「道路交通事故」的要件以及何謂「重大道路交通事故」？（25 分）","pt":25}]}];
